{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2165-11-03 21:25:00",
      "speaker": "Doctor",
      "text": "Hello, I’m Dr. Lee, one of the surgical team. You’re here because of issues with your fistula, correct?"
    },
    {
      "turn_number": 2,
      "time": "2165-11-03 21:26:00",
      "speaker": "Patient",
      "text": "Yes, that’s right. The scab on my arm has been getting wetter, and I’ve had some bleeding after dialysis."
    },
    {
      "turn_number": 3,
      "time": "2165-11-03 21:27:00",
      "speaker": "Doctor",
      "text": "I see. And you’ve noticed this more since your last visit?"
    },
    {
      "turn_number": 4,
      "time": "2165-11-03 21:28:00",
      "speaker": "Patient",
      "text": "Yes, it’s definitely worse. I’m worried it might burst or get infected."
    },
    {
      "turn_number": 5,
      "time": "2165-11-03 21:29:00",
      "speaker": "Doctor",
      "text": "We’re concerned about that too. The fistula has developed an aneurysm, which means a weak spot is bulging. That’s likely why the scab isn’t healing well."
    },
    {
      "turn_number": 6,
      "time": "2165-11-03 21:30:00",
      "speaker": "Patient",
      "text": "Oh, I didn’t know it was that serious. What does that mean for me?"
    },
    {
      "turn_number": 7,
      "time": "2165-11-03 21:31:00",
      "speaker": "Doctor",
      "text": "It means we need to revise the fistula to prevent further bleeding. We discussed two options before—you chose the jump graft, right?"
    },
    {
      "turn_number": 8,
      "time": "2165-11-03 21:32:00",
      "speaker": "Patient",
      "text": "Yes, I didn’t want a catheter if we could avoid it."
    },
    {
      "turn_number": 9,
      "time": "2165-11-03 21:33:00",
      "speaker": "Doctor",
      "text": "Good choice. The jump graft will let us fix the fistula while still using the graft for dialysis during healing."
    },
    {
      "turn_number": 10,
      "time": "2165-11-03 21:34:00",
      "speaker": "Patient",
      "text": "When will the surgery happen?"
    },
    {
      "turn_number": 11,
      "time": "2165-11-03 21:35:00",
      "speaker": "Doctor",
      "text": "We’re scheduling it for tomorrow morning. Tonight, we’ll run some labs and make sure you’re stable."
    },
    {
      "turn_number": 12,
      "time": "2165-11-03 21:36:00",
      "speaker": "Patient",
      "text": "Okay. I’ve been feeling a bit tired, but otherwise okay."
    },
    {
      "turn_number": 13,
      "time": "2165-11-03 21:37:00",
      "speaker": "Doctor",
      "text": "That’s common with your kidney disease. Your hemoglobin is low, but we expect that. We’ll monitor your platelets too—they’re a bit low, which could affect bleeding."
    },
    {
      "turn_number": 14,
      "time": "2165-11-03 21:38:00",
      "speaker": "Patient",
      "text": "I’ve had platelet issues before. Is it safe to go through surgery?"
    },
    {
      "turn_number": 15,
      "time": "2165-11-03 21:39:00",
      "speaker": "Doctor",
      "text": "We’ve reviewed your history. Your platelets are stable, and we’ll take precautions. The benefits of fixing the fistula outweigh the risks."
    },
    {
      "turn_number": 16,
      "time": "2165-11-04 07:00:00",
      "speaker": "Doctor",
      "text": "Good morning. Your labs look stable. We’re moving forward with surgery today."
    },
    {
      "turn_number": 17,
      "time": "2165-11-04 07:01:00",
      "speaker": "Patient",
      "text": "Okay, I’m ready. Will I be out for the whole thing?"
    },
    {
      "turn_number": 18,
      "time": "2165-11-04 07:02:00",
      "speaker": "Doctor",
      "text": "Yes, it’s an open procedure under general anesthesia. The surgeon will place a bovine graft from your brachial artery to the upper arm vein."
    },
    {
      "turn_number": 19,
      "time": "2165-11-04 07:03:00",
      "speaker": "Patient",
      "text": "Bovine? Like from a cow?"
    },
    {
      "turn_number": 20,
      "time": "2165-11-04 07:04:00",
      "speaker": "Doctor",
      "text": "Yes, it’s a processed tissue graft. It’s commonly used and works well for patients like you."
    },
    {
      "turn_number": 21,
      "time": "2165-11-04 12:30:00",
      "speaker": "Doctor",
      "text": "The surgery went well. The jump graft is in place, and the fistula is revised. You’re in the recovery unit now."
    },
    {
      "turn_number": 22,
      "time": "2165-11-04 12:31:00",
      "speaker": "Patient",
      "text": "That’s a relief. Is the graft working?"
    },
    {
      "turn_number": 23,
      "time": "2165-11-04 12:32:00",
      "speaker": "Doctor",
      "text": "Yes, there’s a good thrill—meaning blood is flowing well. We’ll keep an eye on it."
    },
    {
      "turn_number": 24,
      "time": "2165-11-04 12:33:00",
      "speaker": "Patient",
      "text": "I feel a bit nauseous."
    },
    {
      "turn_number": 25,
      "time": "2165-11-04 12:34:00",
      "speaker": "Doctor",
      "text": "That’s common after anesthesia. We’ll give you some Zofran to help."
    },
    {
      "turn_number": 26,
      "time": "2165-11-04 16:00:00",
      "speaker": "Doctor",
      "text": "You’re doing well. Pain is under control, and you’re tolerating liquids. We’ll advance your diet soon."
    },
    {
      "turn_number": 27,
      "time": "2165-11-04 16:01:00",
      "speaker": "Patient",
      "text": "Can I walk a little? I don’t want to stay in bed too long."
    },
    {
      "turn_number": 28,
      "time": "2165-11-04 16:02:00",
      "speaker": "Doctor",
      "text": "Yes, please do. Ambulating helps prevent complications. Just use your walker and take it slow."
    },
    {
      "turn_number": 29,
      "time": "2165-11-05 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. We removed the dressing this morning. There’s a small drop of blood at the incision, but it’s not concerning. We’ve replaced the bandage."
    },
    {
      "turn_number": 30,
      "time": "2165-11-05 08:01:00",
      "speaker": "Patient",
      "text": "Is that normal?"
    },
    {
      "turn_number": 31,
      "time": "2165-11-05 08:02:00",
      "speaker": "Doctor",
      "text": "Yes, minor oozing can happen. The stitches are clean and intact, and the thrill is still strong."
    },
    {
      "turn_number": 32,
      "time": "2165-11-05 08:03:00",
      "speaker": "Patient",
      "text": "When can I go home?"
    },
    {
      "turn_number": 33,
      "time": "2165-11-05 08:04:00",
      "speaker": "Doctor",
      "text": "Today, if all goes well. You’re afebrile, stable, and tolerating food. We’ll confirm with your home care team."
    },
    {
      "turn_number": 34,
      "time": "2165-11-05 10:00:00",
      "speaker": "Doctor",
      "text": "Your home health nurse confirmed they’ll see you tomorrow at 9:30. You’re cleared for discharge."
    },
    {
      "turn_number": 35,
      "time": "2165-11-05 10:01:00",
      "speaker": "Patient",
      "text": "Great. What about my dialysis?"
    },
    {
      "turn_number": 36,
      "time": "2165-11-05 10:02:00",
      "speaker": "Doctor",
      "text": "You’ll use the graft portion for dialysis. The fistula part needs time to heal. Your dialysis team knows the plan."
    },
    {
      "turn_number": 37,
      "time": "2165-11-05 10:03:00",
      "speaker": "Patient",
      "text": "And my medications?"
    },
    {
      "turn_number": 38,
      "time": "2165-11-05 10:04:00",
      "speaker": "Doctor",
      "text": "Resume all your home meds except as noted. We’ve added hydrocodone for pain—take it only if needed, and don’t drive while on it."
    },
    {
      "turn_number": 39,
      "time": "2165-11-05 10:05:00",
      "speaker": "Patient",
      "text": "What signs should I watch for?"
    },
    {
      "turn_number": 40,
      "time": "2165-11-05 10:06:00",
      "speaker": "Doctor",
      "text": "Call if you have fever, increased redness or swelling, pus from the incision, or if the thrill disappears. Also, monitor your weight—call if you gain more than 3 pounds."
    },
    {
      "turn_number": 41,
      "time": "2165-11-05 10:07:00",
      "speaker": "Patient",
      "text": "Got it. Thank you for explaining everything."
    },
    {
      "turn_number": 42,
      "time": "2165-11-05 10:08:00",
      "speaker": "Doctor",
      "text": "You’re welcome. You did well. Take care, and see you at follow-up."
    },
    {
      "turn_number": 43,
      "time": "2165-11-05 12:00:00",
      "speaker": "Doctor",
      "text": "Just a quick check before you leave—we’re confirming your incision is clean and you understand your care instructions."
    },
    {
      "turn_number": 44,
      "time": "2165-11-05 12:01:00",
      "speaker": "Patient",
      "text": "Yes, I’ll keep it dry, no baths, and watch for redness or fever."
    },
    {
      "turn_number": 45,
      "time": "2165-11-05 12:02:00",
      "speaker": "Doctor",
      "text": "Perfect. And remember, no heavy lifting until your surgeon clears you."
    },
    {
      "turn_number": 46,
      "time": "2165-11-05 12:03:00",
      "speaker": "Patient",
      "text": "Understood. I’ll take it easy."
    },
    {
      "turn_number": 47,
      "time": "2165-11-05 12:04:00",
      "speaker": "Doctor",
      "text": "You’re all set. The transport team will take you home shortly."
    },
    {
      "turn_number": 48,
      "time": "2165-11-05 14:00:00",
      "speaker": "Doctor",
      "text": "One last thing—we’ve scheduled your dialysis for tomorrow. They’ll use the graft carefully."
    },
    {
      "turn_number": 49,
      "time": "2165-11-05 14:01:00",
      "speaker": "Patient",
      "text": "Thank you. I feel much better knowing this is fixed."
    },
    {
      "turn_number": 50,
      "time": "2165-11-05 14:02:00",
      "speaker": "Doctor",
      "text": "We’re glad. Take care, and call if anything comes up."
    },
    {
      "turn_number": 51,
      "time": "2165-11-05 16:00:00",
      "speaker": "Doctor",
      "text": "Just confirming—your home nurse confirmed arrival at 0930 tomorrow. Any last questions?"
    },
    {
      "turn_number": 52,
      "time": "2165-11-05 16:01:00",
      "speaker": "Patient",
      "text": "No, I think I’ve got it all. Thanks again."
    },
    {
      "turn_number": 53,
      "time": "2165-11-05 16:02:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Have a safe trip home."
    },
    {
      "turn_number": 54,
      "time": "2165-11-05 18:00:00",
      "speaker": "Doctor",
      "text": "Final check: vitals stable, incision clean, pain controlled. You’re officially discharged."
    },
    {
      "turn_number": 55,
      "time": "2165-11-05 18:01:00",
      "speaker": "Patient",
      "text": "Thank you, Doctor. I appreciate all your help."
    },
    {
      "turn_number": 56,
      "time": "2165-11-05 18:02:00",
      "speaker": "Doctor",
      "text": "You’re very welcome. Take care and see you soon."
    }
  ],
  "summary": {
    "admission_start": "2165-11-03 21:25:00",
    "admission_end": "2165-11-05 19:30:00",
    "summary_paragraph": "A 52-year-old female with end-stage renal disease on hemodialysis was admitted due to worsening scabbing and bleeding from her left brachiobasilic AV fistula, found to have an aneurysm. She underwent a bovine jump graft revision to address the complication while preserving dialysis access. The procedure was successful, with no intraoperative complications. Postoperatively, she experienced mild nausea managed with antiemetics, and minor oozing from the incision was noted but resolved with dressing replacement. She remained hemodynamically stable, afebrile, and tolerated oral intake and ambulation. She was discharged home with home health services, with instructions for incision care, activity restrictions, and close monitoring for signs of infection or graft dysfunction. Follow-up was arranged with her surgical and dialysis teams.",
    "problems": [
      "End stage renal disease",
      "Aneurysm of a fistula",
      "Hemorrhage due to vascular prosthetic devices, implants and grafts, initial encounter",
      "Thrombocytopenia, unspecified",
      "Dependence on renal dialysis",
      "Surgical operation with anastomosis, bypass or graft as the cause of abnormal reaction of the patient, or of later complication, without mention of misadventure at the time of the procedure"
    ]
  }
}
